import{_ as s,o as t,c as n,ag as e}from"./chunks/framework.CmaAMB6e.js";const g=JSON.parse('{"title":"06 · 消息队列","description":"","frontmatter":{"概念":"消息队列","技能":"system-design","阶段":"2-基础组件","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"system-design/concepts/06-message-queue.md","filePath":"system-design/concepts/06-message-queue.md","lastUpdated":null}'),p={name:"system-design/concepts/06-message-queue.md"};function i(r,a,d,l,o,c){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="_06-·-消息队列" tabindex="-1">06 · 消息队列 <a class="header-anchor" href="#_06-·-消息队列" aria-label="Permalink to &quot;06 · 消息队列&quot;">​</a></h1><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>消息队列（Message Queue, MQ）是「生产者」和「消费者」之间的<strong>异步管道</strong>：生产者只负责把消息投递到队列就返回，消费者在自己的节奏里消费。它解决三类问题——<strong>解耦</strong>（下单服务不用知道短信服务长什么样）、<strong>削峰</strong>（秒杀洪峰被队列缓冲，下游按能力消费）、<strong>异步</strong>（耗时操作不阻塞主请求）。</p><p>对前端工程师来说，MQ 最像<strong>事件总线</strong>：Vue 的 <code>mitt</code>、React 里的发布订阅、微前端的事件通信，都是「发消息的人不认识收消息的人」。区别在于：前端事件总线是进程内的、无持久化的、挂了就丢了；MQ 是跨服务的、持久化的、可重放可追踪的——<strong>把事件总线的可靠性提升到生产级</strong>。</p><p>本章覆盖：为什么需要 MQ、三大代表怎么选、生产消费模型、分区与消费组、消息可靠性（至少一次 vs 恰好一次）、死信队列。核心心智是：<strong>MQ 不保证「不丢不重」，它只保证「可追踪」</strong>——可靠性靠消费者幂等来兜底。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-为什么需要-mq-同步调用的痛点" tabindex="-1">1. 为什么需要 MQ：同步调用的痛点 <a class="header-anchor" href="#_1-为什么需要-mq-同步调用的痛点" aria-label="Permalink to &quot;1. 为什么需要 MQ：同步调用的痛点&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同步调用（无 MQ）：</span></span>
<span class="line"><span>  下单请求 ──► 订单服务 ──► 短信服务（50ms）</span></span>
<span class="line"><span>                    └──────► 积分服务（30ms）</span></span>
<span class="line"><span>                    └──────► 统计服务（20ms）</span></span>
<span class="line"><span>  → 用户等待 100ms+，短信服务一挂，下单整个失败（级联故障）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>异步解耦（有 MQ）：</span></span>
<span class="line"><span>  下单请求 ──► 订单服务 ──► 写库 + 投递「订单创建」事件，立即返回</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    ▼</span></span>
<span class="line"><span>              [订单事件队列]</span></span>
<span class="line"><span>              ────┬────┬────┬────</span></span>
<span class="line"><span>                  ▼    ▼    ▼    ▼</span></span>
<span class="line"><span>              短信   积分   统计  推荐（各自独立消费，互不阻塞）</span></span>
<span class="line"><span>  → 用户只等写库的时间；下游服务慢/挂都不影响下单</span></span></code></pre></div><p>三大收益对应三个场景：<strong>解耦</strong>（新增一个「优惠券服务」只需订阅事件，不用改下单代码）、<strong>削峰</strong>（秒杀 10 万 QPS 打进来，下游数据库只承受 1000 QPS）、<strong>异步</strong>（邮件发送从请求链路挪到后台）。代价是引入了「最终一致」与「消息可追踪」的复杂度——<strong>没有免费的解耦</strong>。</p><h4 id="_2-三大代表选型" tabindex="-1">2. 三大代表选型 <a class="header-anchor" href="#_2-三大代表选型" aria-label="Permalink to &quot;2. 三大代表选型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>Kafka</th><th>RabbitMQ</th><th>Redis Stream</th></tr></thead><tbody><tr><td>定位</td><td>日志/事件流（高吞吐）</td><td>业务消息路由</td><td>轻量流（不引新组件）</td></tr><tr><td>吞吐</td><td>百万级条/s（顺序写盘）</td><td>万级条/s</td><td>十万级（内存）</td></tr><tr><td>路由能力</td><td>弱（topic 只能广播）</td><td>强（exchange 按 key 路由）</td><td>弱（按 stream）</td></tr><tr><td>可靠性</td><td>靠副本 + ack</td><td>成熟（confirm/ack）</td><td>弱（依赖持久化配置）</td></tr><tr><td>典型场景</td><td>埋点日志、订单事件流</td><td>任务分发、按条件路由</td><td>简单削峰、临时任务</td></tr><tr><td>运维成本</td><td>高（依赖 ZooKeeper/KRaft）</td><td>中</td><td>低（复用 Redis）</td></tr></tbody></table><p>选型口诀：<strong>高吞吐事件流选 Kafka，灵活路由业务消息选 RabbitMQ，已有 Redis 且场景简单就用 Redis Stream</strong>。选型是权衡不是攀比——为「每天几百条」的消息上 Kafka 集群，是拿大炮打蚊子。</p><h4 id="_3-生产者-消费者模型" tabindex="-1">3. 生产者 / 消费者模型 <a class="header-anchor" href="#_3-生产者-消费者模型" aria-label="Permalink to &quot;3. 生产者 / 消费者模型&quot;">​</a></h4><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P1[生产者1 订单服务] --&gt; T[(Topic: order_events)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P2[生产者2 退款服务] --&gt; T</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T --&gt; C1[消费者1 短信服务]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T --&gt; C2[消费者2 积分服务]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T --&gt; C3[消费者3 统计服务]</span></span></code></pre></div><p>核心概念：<strong>Topic（主题）</strong> 是消息的逻辑分类；生产者投递到 Topic，消费者订阅 Topic。任何服务都可以同时是生产者和消费者——<strong>服务之间的耦合从「代码调用」降级为「约定 Topic 与消息格式」</strong>。</p><h4 id="_4-分区与消费组" tabindex="-1">4. 分区与消费组 <a class="header-anchor" href="#_4-分区与消费组" aria-label="Permalink to &quot;4. 分区与消费组&quot;">​</a></h4><p>这是 Kafka 吞吐的关键：一个 Topic 分成多个 <strong>Partition（分区）</strong>，消息按 key 哈希进分区，分区是并行与顺序的单位：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Topic: order_events（8 个分区）</span></span>
<span class="line"><span>  分区0: [order#1] [order#2] ...</span></span>
<span class="line"><span>  分区1: [order#3] [order#4] ...</span></span>
<span class="line"><span>  ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>消费者组（同组内分工消费，组间各自独立）：</span></span>
<span class="line"><span>  组A（短信服务，3 个实例）： 分区0→实例1  分区1→实例2  ...</span></span>
<span class="line"><span>  组B（统计服务，2 个实例）： 分区0→实例1  ...（与组A无关）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关键规则：</span></span>
<span class="line"><span>  同一分区内的消息 → 顺序消费（同组内由同一消费者处理）</span></span>
<span class="line"><span>  同组内分区数 ≥ 消费者数，否则有消费者空转</span></span>
<span class="line"><span>  不同分区之间 → 消息乱序（不同订单之间顺序无意义）</span></span></code></pre></div><p><strong>「分区内有序、分区间无序」是全局设计原则</strong>：需要保证顺序的业务（同一订单的「创建→支付→发货」事件）必须用同一个分区键（订单号），否则事件乱序会导致状态机跑飞。</p><h4 id="_5-消息可靠性-至少一次-恰好一次" tabindex="-1">5. 消息可靠性：至少一次 / 恰好一次 <a class="header-anchor" href="#_5-消息可靠性-至少一次-恰好一次" aria-label="Permalink to &quot;5. 消息可靠性：至少一次 / 恰好一次&quot;">​</a></h4><p>投递语义是一个光谱，没有免费的完美：</p><table tabindex="0"><thead><tr><th>语义</th><th>机制</th><th>代价</th><th>适用</th></tr></thead><tbody><tr><td>至少一次</td><td>消费者处理成功后 ack；失败不 ack 重新投递</td><td><strong>可能重复消费</strong></td><td>默认选择（配幂等）</td></tr><tr><td>至多一次</td><td>收到即 ack，不重试</td><td>可能丢消息</td><td>可容忍丢失的日志/埋点</td></tr><tr><td>恰好一次</td><td>事务/幂等键去重</td><td>性能与复杂度最高</td><td>支付、账务等必须精确</td></tr></tbody></table><p><strong>生产实践：至少一次 + 消费幂等</strong>。因为「恰好一次」的实现依赖端到端事务，代价极高；更简单的是「至少一次 + 消费端用唯一键去重」：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>消费端幂等实现：</span></span>
<span class="line"><span>  ① 消息带全局唯一 id（或业务键：订单号+事件类型）</span></span>
<span class="line"><span>  ② 消费前查「已处理表」：已存在则跳过（INSERT IGNORE / 唯一索引）</span></span>
<span class="line"><span>  ③ 处理业务 + 写已处理记录，在同一个事务里 → 原子</span></span></code></pre></div><h4 id="_6-死信队列-dlq" tabindex="-1">6. 死信队列（DLQ） <a class="header-anchor" href="#_6-死信队列-dlq" aria-label="Permalink to &quot;6. 死信队列（DLQ）&quot;">​</a></h4><p>消费失败重试 N 次（如 3 次）后仍失败的消息，进<strong>死信队列</strong>，人工/定时任务介入排查——<strong>避免坏消息无限阻塞队列</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>消费失败 → 重试队列（延迟 1s/5s/30s）→ 仍失败 → DLQ（死信队列）</span></span>
<span class="line"><span>                                                    │</span></span>
<span class="line"><span>                                          ┌─────────┴─────────┐</span></span>
<span class="line"><span>                                          ▼                   ▼</span></span>
<span class="line"><span>                                    告警：通知值班人员      人工分析/补偿</span></span></code></pre></div><p>DLQ 是「系统自己兜不住」的最终防线，常见死因：下游服务长时间不可用、消息格式与代码不兼容、脏数据。死信也要监控告警——<strong>死信堆积是重大事故的早期信号</strong>（例如下单事件死信堆积 = 下游正在丢失订单处理）。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>为「快」而异步，忘记顺序</strong>：同一实体的多个事件散落到不同分区，消费端状态机乱序错乱；关键事件必须同 key。</li><li><strong>只 ack 不幂等</strong>：用了「至少一次」却没做幂等，网络重试导致重复发短信、重复加积分。</li><li><strong>把 MQ 当数据库</strong>：消息无限保留、全量查询历史，MQ 的存储不是为查询设计的。</li><li><strong>消费速度跟不上生产</strong>：分区数 &lt; 消费者数时扩容无效；监控 lag（积压量）是 MQ 运维的核心指标。</li><li><strong>同步调用硬改成 MQ</strong>：下游要立刻拿到结果（如查余额），异步会让用户等不到响应；MQ 只适合「可以等」的业务。</li><li><strong>死信无人问津</strong>：DLQ 没接告警，消息悄悄堆积，业务缺失几小时才发现。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：用 Redis Stream 实现一个最小「下单 → 发短信」：生产者投递 <code>order_created</code>，消费者消费并打印，模拟消费失败重试。</li><li><strong>进阶</strong>：给消费者加幂等（已处理表 + 唯一键），并用「至少一次」语义模拟重复投递，验证不会重复处理。</li><li><strong>综合</strong>：为电商设计订单事件流：<code>order_created → order_paid → order_shipped → order_completed</code>，规定分区键、消费者组划分、各下游（短信/库存/统计）的可靠性要求与 DLQ 处理流程。</li></ol><blockquote><p>用 <code>/practice system-design 消息队列</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构概念</th><th>系统设计对应</th></tr></thead><tbody><tr><td>事件总线（mitt / EventEmitter）</td><td>消息队列（跨服务版事件总线）</td></tr><tr><td>Redux 异步 action（dispatch 后不管）</td><td>异步解耦：投递消息后立即返回</td></tr><tr><td>微前端应用间通信（事件 + 约定协议）</td><td>Topic 契约：消息格式与语义约定</td></tr><tr><td>事件监听器内存泄漏（忘解绑）</td><td>消费者挂了不 ack（消息积压）</td></tr><tr><td>React 事件顺序（冒泡阶段）</td><td>分区内有序消费</td></tr><tr><td>前端防重复提交（幂等按钮）</td><td>消费幂等（唯一键去重）</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://kafka.apache.org/documentation/" target="_blank" rel="noreferrer">Kafka 官方文档（设计核心：分区与消费组）</a></li><li><a href="https://www.rabbitmq.com/tutorials" target="_blank" rel="noreferrer">RabbitMQ 官方教程</a></li><li><a href="https://redis.io/docs/data-types/streams/" target="_blank" rel="noreferrer">Redis Stream 官方文档</a></li></ul>`,37)])])}const b=s(p,[["render",i]]);export{g as __pageData,b as default};
